// AUTO-GENERATED healing-scene group cover presets (640x240 JPEG data-URIs,
// ~10kb each) — illustrated calm landscapes members can pick from; kept
// identical in the backend (lazy-assigns them to groups without a cover) and
// both clients (the picker UI). Regenerated 2026-07-19 after user feedback
// (v1 plain gradients replaced with full scenes).

export type GroupCoverPreset = { key: string; name: string; uri: string };

export const GROUP_COVER_PRESETS: GroupCoverPreset[] = [
  {
    key: "lavender",
    name: "Misty mountains",
    uri: "data:image/jpeg;base64,",
  },
  {
    key: "sage",
    name: "Rolling meadow",
    uri: "data:image/jpeg;base64,",
  },
  {
    key: "ocean",
    name: "Ocean sunrise",
    uri: "data:image/jpeg;base64,",
  },
  {
    key: "sunrise",
    name: "Zen stones",
    uri: "data:image/jpeg;base64,",
  },
  {
    key: "night",
    name: "Moonlit calm",
    uri: "data:image/jpeg;base64,",
  },
  {
    key: "lotus",
    name: "Lotus pond",
    uri: "data:image/jpeg;base64,",
  },
];

/** Deterministic preset for a group that never chose one (stable per id). */
export const presetCoverFor = (id: string) => {
  let hash = 0;
  for (const ch of id) hash = (hash * 31 + ch.charCodeAt(0)) >>> 0;
  return GROUP_COVER_PRESETS[hash % GROUP_COVER_PRESETS.length];
};
